# MAGIC <span style="color:#6E8B6E;font-style:italic;"># Convert the logged model into a Spark UDF</span>
# MAGIC model_udf = mlflow.pyfunc.spark_udf(spark, model_path)
# MAGIC &#8203;
# MAGIC <span style="color:#6E8B6E;font-style:italic;"># Apply it in parallel across DataFrame partitions</span>
# MAGIC df = input_data.withColumn(<span style="color:#2E8B57;">&quot;prediction&quot;</span>, model_udf(<span style="color:#2E8B57;">&quot;features&quot;</span>))</pre></div></div><div style="border-left:4px solid #FF5F46;background:#FFF6F4;padding:12px 16px;border-radius:0 6px 6px 0;margin-top:16px;font-size:14.5px;line-height:1.55;color:#33414B;"><b>Note:</b> the Spark approach loads the model only once per Python process, ensuring efficient reuse during inference.</div>
